"""Discover the symbol fields available in a KiCad project, for the BOM tab."""

import re
from pathlib import Path

# Fields generated by KiCad's BOM exporter.
GENERATED_FIELDS = [
    "${ITEM_NUMBER}",
    "${QUANTITY}",
    "${DNP}",
    "${EXCLUDE_FROM_BOM}",
    "${EXCLUDE_FROM_BOARD}",
    "${EXCLUDE_FROM_SIM}",
]
STANDARD_FIELDS = ["Reference", "Value", "Footprint", "Datasheet", "Description"]

DEFAULT_LABELS = {
    "${ITEM_NUMBER}": "#",
    "${QUANTITY}": "Qty",
    "${DNP}": "DNP",
    "${EXCLUDE_FROM_BOM}": "Excluded from BOM",
    "${EXCLUDE_FROM_BOARD}": "Excluded from board",
    "${EXCLUDE_FROM_SIM}": "Excluded from sim",
}

# Order of the columns ticked by default.
DEFAULT_INCLUDED = ["${ITEM_NUMBER}", "Reference", "Value", "${QUANTITY}", "Footprint"]
DEFAULT_GROUP_BY = {"Value", "Footprint"}

# Custom fields that look like manufacturer / part-number fields are ticked by default.
_MPN_RE = re.compile(r"manufacturer|\bmfr|\bmpn\b|part.?number|\bmfg", re.IGNORECASE)

_TOKEN_RE = re.compile(r'"(?:[^"\\]|\\.)*"|[()]|[^\s()"]+')


def _top_level_forms(text):
    """Yield the text of each direct child form of the root (kicad_sch ...) form."""
    depth = 0
    start = None
    for m in _TOKEN_RE.finditer(text):
        tok = m.group(0)
        if tok == "(":
            depth += 1
            if depth == 2:
                start = m.start()
        elif tok == ")":
            if depth == 2 and start is not None:
                yield text[start : m.end()]
                start = None
            depth -= 1


_SYMBOL_HEAD_RE = re.compile(r"^\(\s*symbol\b")
_PROPERTY_RE = re.compile(r'\(\s*property\s+"((?:[^"\\]|\\.)*)"')


def project_symbol_fields(project_dir):
    """Return the custom field names used by placed symbols, in first-seen order.

    Library symbol definitions (lib_symbols) and sheet properties are ignored.
    """
    names = []
    seen = set(STANDARD_FIELDS)
    for sch in sorted(Path(project_dir).rglob("*.kicad_sch")):
        try:
            text = sch.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        for form in _top_level_forms(text):
            if not _SYMBOL_HEAD_RE.match(form):
                continue
            for m in _PROPERTY_RE.finditer(form):
                name = m.group(1).replace('\\"', '"')
                if name.startswith("ki_") or name in seen:
                    continue
                seen.add(name)
                names.append(name)
    return names


def default_bom_fields(project_dir):
    """Default BOM table rows: [{field, include, label, group_by}] in column order."""
    custom = project_symbol_fields(project_dir)
    available = STANDARD_FIELDS + custom + GENERATED_FIELDS
    included = list(DEFAULT_INCLUDED)
    for name in custom:
        if _MPN_RE.search(name):
            included.append(name)
    rows = []
    for name in included + [n for n in available if n not in included]:
        is_in = name in included
        rows.append(
            {
                "field": name,
                "include": is_in,
                "label": DEFAULT_LABELS.get(name, name),
                "group_by": is_in and (name in DEFAULT_GROUP_BY or bool(_MPN_RE.search(name))),
            }
        )
    return rows


def merge_bom_fields(saved, defaults):
    """Apply a saved table on top of the project defaults.

    Saved rows keep their order and settings; fields that disappeared from the
    project are dropped (generated fields always exist); new fields are appended
    unticked.
    """
    if not saved:
        return [dict(row) for row in defaults]
    by_name = {row["field"]: row for row in defaults}
    rows = []
    for item in saved or []:
        if not isinstance(item, dict):
            continue
        name = str(item.get("field", ""))
        if name not in by_name or any(r["field"] == name for r in rows):
            continue
        rows.append(
            {
                "field": name,
                "include": bool(item.get("include", False)),
                "label": str(item.get("label") or by_name[name]["label"]),
                "group_by": bool(item.get("group_by", False)),
            }
        )
    known = {r["field"] for r in rows}
    for row in defaults:
        if row["field"] not in known:
            rows.append(dict(row, include=False, group_by=False))
    return rows
